def solve(M):
    A = 0
    for n in range(1, M):
        denom = 1
        for k in range(1, n + 1):
            denom *= (k + M)
        A += (M**n) / denom

    B = 0
    for n in range(1, M):
        prod = 1
        for k in range(1, n + 1):
            prod *= (1 - k/M)
        B += prod

    return A - B

for m in range(1, 11):
    print(f"M={m}, S={solve(m)}")

def solve_A_only(M):
    A = 0
    term = 1
    for n in range(1, M):
        term *= M / (M + n)
        A += term
    return A

for m in range(1, 11):
    print(f"A({m}) = {solve_A_only(m)}")
